/**
 * Base64-encoded TTF font bytes, generated from `packages/pdf/assets/fonts/*.ttf` so
 * `fonts.ts` can pass them to `@react-pdf/renderer`'s `Font.register` as `data:` URLs instead of
 * a file-system path. See fonts.ts for why: a path baked in at import time (even
 * `import.meta.url`-relative) becomes an absolute build-machine path once webpack
 * bundles this into a Vercel serverless function, and that path does not exist on
 * Vercel's filesystem at request time.
 *
 * Regenerate after replacing a font file:
 *   node -e "const fs=require(\"fs\");console.log(fs.readFileSync(\"assets/fonts/Inter-Regular.ttf\").toString(\"base64\"))"
 * (run from `packages/pdf`, one line per constant below, from `packages/pdf`).
 */

export const INTER_REGULAR_TTF_BASE64 =
  ""

export const INTER_SEMIBOLD_TTF_BASE64 =
  ""

export const HIND_SILIGURI_REGULAR_TTF_BASE64 =
  ""

export const HIND_SILIGURI_SEMIBOLD_TTF_BASE64 =
  ""

